const { accel, gyro, mag } = msg.payload;
const roll = Math.atan2(accel.y, accel.z);
const pitch = Math.atan2(-accel.x, Math.sqrt(accel.y * accel.y + accel.z * accel.z));
// map the magnetometer frame into the accelerometer frame
const bx = mag.x, by = -mag.y, bz = -mag.z;
const xh = bx * Math.cos(pitch) + bz * Math.sin(pitch);
const yh = bx * Math.sin(roll) * Math.sin(pitch) + by * Math.cos(roll) - bz * Math.sin(roll) * Math.cos(pitch);
const heading = (Math.atan2(-yh, xh) * 180 / Math.PI + 360) % 360;
msg.payload = {
    roll: roll * 180 / Math.PI,
    pitch: pitch * 180 / Math.PI,
    heading,
    gyroMagnitude: Math.sqrt(gyro.x * gyro.x + gyro.y * gyro.y + gyro.z * gyro.z)
};
return msg;
